import {useMutation, type UseMutationOptions, type UseMutationResult} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {UpdateAlertAssigneesError, type UpdateAlertAssigneesResponse} from '../types'

export type UpdateAlertAssigneesRequest = {
  assigneeIds: string[] | number[]
}

export function useUpdateAlertAssigneesMutation<
  Response extends UpdateAlertAssigneesResponse = UpdateAlertAssigneesResponse,
  TContext = unknown,
>(
  path: string,
  options?: Omit<UseMutationOptions<Response | null, Error, UpdateAlertAssigneesRequest, TContext>, 'mutationFn'>,
): UseMutationResult<Response | null, Error, UpdateAlertAssigneesRequest, TContext> {
  return useMutation({
    mutationFn: async request => {
      const response = await reactFetchJSON(path, {
        method: 'PATCH',
        body: {
          assignee_ids: request.assigneeIds,
        },
      })
      if (!response.ok) {
        throw new UpdateAlertAssigneesError(`${response.status} on ${response.url}`, response)
      }
      return response.json()
    },
    ...options,
  })
}
