export type Assignee = {
  id: number
  login: string
  name: string | null
  avatarUrl: string
  profilePath: string
  isCopilot: boolean
}

export type AvailableAssigneesResponse = {
  users: Assignee[]
}

export type UpdateAlertAssigneesResponse = {
  assignees: Assignee[]
  isCopilotAssignmentNew: boolean
}

export class UpdateAlertAssigneesError extends Error {
  readonly response: Response
  constructor(message: string, response: Response) {
    super(message)
    this.response = response
    this.name = 'UpdateAlertAssigneesError'
  }
}
